import { requireUser } from '@/lib/auth';
import { json, route, HttpError } from '@/lib/http';
import { todayUtc } from '@/lib/time';
import { listForPractitionerOnDay } from '@/repos/appointments';

/** The signed-in practitioner's appointments for today (UTC), for the day view. */
export const GET = route(async (req) => {
  const user = await requireUser(req);
  if (user.role !== 'practitioner' || !user.practitionerId) throw new HttpError(403, 'forbidden');
  const day = todayUtc();
  const rows = await listForPractitionerOnDay(user.practitionerId, day);
  return json({
    day,
    appointments: rows.map((a) => ({
      id: a.id,
      startsAt: a.starts_at,
      endsAt: a.ends_at,
      status: a.status,
      patient: { id: a.patient_id, firstName: a.patient_first_name, lastName: a.patient_last_name },
    })),
  });
});
import { execute, query } from '@/lib/db';
import { newId } from '@/lib/ids';
import { utcDayBounds } from '@/lib/time';

export interface AppointmentRow {
  id: string;
  org_id: string;
  patient_id: string;
  practitioner_id: string;
  starts_at: Date;
  ends_at: Date;
  status: 'booked' | 'cancelled' | 'completed';
  visit_reason: string | null;
  notes: string | null;
  created_by_user_id: string;
  created_at: Date;
}

export async function listForPatient(patientId: string): Promise<AppointmentRow[]> {
  return query<AppointmentRow>(
    'SELECT * FROM appointments WHERE patient_id = ? ORDER BY starts_at',
    [patientId],
  );
}

/**
 * A practitioner's appointments for one UTC day, limited to patients they still have
 * access to. Rows include the patient's name for display.
 */
export async function listForPractitionerOnDay(
  practitionerId: string,
  day: string,
): Promise<Array<AppointmentRow & { patient_first_name: string; patient_last_name: string }>> {
  const { start, end } = utcDayBounds(day);
  return query(
    `SELECT a.*, p.first_name AS patient_first_name, p.last_name AS patient_last_name
       FROM appointments a
       JOIN patients p ON p.id = a.patient_id
       JOIN care_team ct ON ct.practitioner_id = a.practitioner_id AND ct.patient_id = a.patient_id AND ct.active = 1
      WHERE a.practitioner_id = ? AND a.starts_at >= ? AND a.starts_at < ? AND a.status <> 'cancelled'
      ORDER BY a.starts_at`,
    [practitionerId, start, end],
  );
}

export async function createAppointment(input: {
  orgId: string;
  patientId: string;
  practitionerId: string;
  startsAt: Date;
  endsAt: Date;
  visitReason: string | null;
  createdByUserId: string;
}): Promise<string> {
  const id = newId('apt');
  await execute(
    `INSERT INTO appointments (id, org_id, patient_id, practitioner_id, starts_at, ends_at, status, visit_reason, created_by)
     VALUES (?, ?, ?, ?, ?, ?, 'booked', ?, ?)`,
    [id, input.orgId, input.patientId, input.practitionerId, input.startsAt, input.endsAt, input.visitReason, input.createdByUserId],
  );
  return id;
}
import { execute, queryOne } from '@/lib/db';

export async function hasActiveAccess(practitionerId: string, patientId: string): Promise<boolean> {
  const row = await queryOne(
    'SELECT 1 AS ok FROM care_team WHERE practitioner_id = ? AND patient_id = ? AND active = 1',
    [practitionerId, patientId],
  );
  return row !== null;
}

/** Removes a practitioner's access to a patient. Returns false if there was no active access. */
export async function revokeAccess(practitionerId: string, patientId: string): Promise<boolean> {
  const res = await execute(
    'UPDATE care_team SET active = 0, revoked_at = UTC_TIMESTAMP(3) WHERE practitioner_id = ? AND patient_id = ? AND active = 1',
    [practitionerId, patientId],
  );
  return res.affectedRows > 0;
}
import { z } from 'zod';
import { requireUser, requireRole } from '@/lib/auth';
import { json, readJson, route, HttpError } from '@/lib/http';
import { audit } from '@/lib/audit';
import { getPatient } from '@/repos/patients';
import { getPractitioner } from '@/repos/practitioners';
import { revokeAccess } from '@/repos/careTeam';

const Body = z.object({ practitionerId: z.string().min(1), patientId: z.string().min(1) });

/** An admin removes a practitioner's access to a patient. */
export const POST = route(async (req) => {
  const user = await requireUser(req);
  requireRole(user, 'admin');
  const input = Body.parse(await readJson(req));
  const [practitioner, patient] = await Promise.all([getPractitioner(input.practitionerId), getPatient(input.patientId)]);
  if (!practitioner || !patient || practitioner.org_id !== user.orgId || patient.org_id !== user.orgId) {
    throw new HttpError(404, 'not_found');
  }
  const changed = await revokeAccess(practitioner.id, patient.id);
  await audit(user, 'care_team.revoke', 'patient', patient.id);
  return json({ revoked: changed });
});
import Redis from 'ioredis';
import { env } from './env';

let client: Redis | undefined;

export function getRedis(): Redis {
  if (!client) {
    client = new Redis(env.redisUrl, { maxRetriesPerRequest: 2, lazyConnect: false });
  }
  return client;
}

/** All keys written by the app start with this prefix. */
export const KEY_PREFIX = 'clinic:';

export async function closeRedis(): Promise<void> {
  if (client) {
    await client.quit();
    client = undefined;
  }
}
